sys.modules['explain_diff'] = explain_diff
_features_source = '"""Pair feature table for candidate pairs (master plan SS14, groups A-H).\n\nGroups:\n  A  string similarities (rapidfuzz, vectorised `cpdist`) on norm/fold name\n     and address, plus token / IDF-weighted token / char-3-gram Jaccard;\n  B  explain-the-difference features for name and address (explain_diff.py);\n  C  number agreement (explain_diff.number_features);\n  D  embedding cosines: not available (dense encoding of all records is\n     infeasible at ~400 rec/s, memory.md SS5) -> omitted;\n  E  structure and missingness (token counts, length ratio, empty flags,\n     postcode / landmark presence, landmark similarity, romanised script);\n  F  blocking meta (channel bits, channel scores, pre-ranker score, rank and\n     gap to the S1\'s best, candidates per S1);\n  G  source (`is_S3`);\n  H  `same_country` is constant 1 (blocking is within-country, EDA E5) -> dropped.\nNo raw tokens, no country values, no IDs. Fine-tuned embeddings are never used\nhere (stage-1 is trained on Half A, plan SS10.3).\n\nPer-pair Python work (groups A-Jaccard, B, C, E) runs in a fork-based process\npool; every worker keeps its own token-relation cache (explain_diff._CACHE).\nRecord tables are shared with the workers through a module global set before\nthe fork, never pickled.\n"""\n\nfrom __future__ import annotations\n\nimport time\n\nimport numpy as np\nimport pandas as pd\n\n\nSPARSE_CHANNELS = ["name_char", "addr_char", "name_tok", "num_key", "name_pair", "addr_pair", "cross_pair"]\nREC_COLS = ["entity_id", "country", "norm_name", "fold_name", "norm_addr", "fold_addr", "name_numbers",\n            "addr_numbers", "house_number", "postcodes", "landmark", "name_romanized"]\n\n# Group A, vectorised: (feature name, record field, scorer name). Scorers were\n# timed per pair (WRatio / Damerau-Levenshtein on addresses cost 20+ us each),\n# so addresses get the cheap ones and Levenshtein replaces Damerau-Levenshtein.\n_RF_SPECS = [(f"norm_name_{s}", "norm_name", s)\n             for s in ("ratio", "partial_ratio", "token_sort_ratio", "token_set_ratio", "WRatio", "jw", "lev")]\n_RF_SPECS += [(f"norm_addr_{s}", "norm_addr", s) for s in ("ratio", "token_set_ratio", "jw", "lev")]\n_RF_SPECS += [(f"{f}_{s}", f, s) for f in ("fold_name", "fold_addr") for s in ("ratio", "jw")]\n# Pre-ranker subset (~8 us/pair): the fastest scorers only.\n_PRE_SPECS = [(f"norm_name_{s}", "norm_name", s) for s in ("ratio", "token_set_ratio", "jw", "lev")]\n_PRE_SPECS += [(f"norm_addr_{s}", "norm_addr", s) for s in ("ratio", "jw", "lev")] + [("fold_name_ratio", "fold_name", "ratio")]\nPRE_RF_FEATURES = [n for n, _, _ in _PRE_SPECS]\nRF_FEATURES = [n for n, _, _ in _RF_SPECS]\n\nPY_FEATURES = (\n    [f"name_{f}" for f in explain_diff.FIELD_FEATURES]\n    + [f"addr_{f}" for f in explain_diff.FIELD_FEATURES]\n    + explain_diff.NUMBER_FEATURES\n    + ["name_tok_jacc", "name_idf_jacc", "name_c3_jacc", "addr_tok_jacc", "addr_idf_jacc", "addr_c3_jacc",\n       "name_len_ratio", "addr_len_ratio", "addr_empty_1", "addr_empty_2", "has_postcode_1", "has_postcode_2",\n       "landmark_1", "landmark_2", "landmark_jacc", "romanized_1", "romanized_2"]\n)\nMETA_FEATURES = (\n    [f"ch_{c}" for c in SPARSE_CHANNELS] + [f"{c}_score" for c in SPARSE_CHANNELS]\n    + ["n_channels", "cheap_score", "cheap_rank", "cheap_gap", "n_cands", "is_S3"]\n)\n# Scale-guard pre-ranker (plan SS12.2 / memory.md SS5): cheap, fully vectorised features only.\nPRERANK_FEATURES = META_FEATURES + PRE_RF_FEATURES\nFEATURES = META_FEATURES + RF_FEATURES + PY_FEATURES\n\n_CTX: dict = {}  # shared with forked workers (see module docstring)\n\n\n# ---------------------------------------------------------------------------\n# Token statistics -> IDF and generic-token lookups\n# ---------------------------------------------------------------------------\n\n\ndef token_lookups(stats: pd.DataFrame, min_df_generic: int = 1000, name_end_ratio: float = 0.7,\n                  addr_type_ratio: float = 0.5) -> dict:\n    """IDF dicts per country and generic-token sets from the NB02 token statistics.\n\n    Generic tokens (legal forms, street types) are frequent AND positional:\n    name tokens mostly in the last two positions, address tokens mostly right\n    after the house number. The frequency floor fixes the NB02 finding that\n    the unfloored likeness score ranks typo variants first (memory.md SS9).\n    No word lists, no country values: the country is only a grouping key.\n\n    Inputs: stats - long token table (field, country, token, df, pos_count, n_docs).\n    Outputs: {"idf": {country: (name_idf, name_default, addr_idf, addr_default)},\n              "generic_name": set, "generic_addr": set}.\n    """\n    out: dict = {"idf": {}}\n    countries = sorted(c for c in stats["country"].unique().tolist() if c != "")\n    for c in countries:\n        ni, nd = corpus_stats.idf_lookup(stats, "norm_name", c)\n        ai, ad = corpus_stats.idf_lookup(stats, "norm_addr", c)\n        out["idf"][c] = (ni, nd, ai, ad)\n    for field, key, ratio in (("norm_name", "generic_name", name_end_ratio), ("norm_addr", "generic_addr", addr_type_ratio)):\n        g = stats[(stats["field"] == field) & (stats["country"] == "")]\n        keep = (g["df"] >= min_df_generic) & (g["pos_count"] / g["df"].clip(lower=1) >= ratio)\n        out[key] = set(g.loc[keep, "token"].tolist()) | {"&"}\n    return out\n\n\n# ---------------------------------------------------------------------------\n# Context shared with workers\n# ---------------------------------------------------------------------------\n\n\ndef set_context(s1: pd.DataFrame, pool: pd.DataFrame, lookups: dict) -> None:\n    """Store the record columns (as Python lists) and lookups for the workers.\n\n    Must be called before `pair_features` (and before any fork).\n    Inputs: s1, pool - record frames with REC_COLS (row order = row ids used\n            by the pair arrays); lookups - output of `token_lookups`.\n    """\n    _CTX.clear()\n    for side, df in (("s", s1), ("p", pool)):\n        for c in REC_COLS[1:]:\n            col = df[c]\n            _CTX[f"{side}_{c}"] = (np.asarray(col, dtype=bool).tolist() if c == "name_romanized"\n                                   else [str(x) for x in col.tolist()])\n        # fresh Python objects for the (subset) records: forked workers then only touch these pages\n        _CTX[f"{side}_arr"] = {c: np.array([str(x) for x in df[c].tolist()], dtype=object)\n                               for c in ("norm_name", "fold_name", "norm_addr", "fold_addr")}\n        _CTX[f"{side}_len"] = {c: np.fromiter(map(len, a), dtype=np.int32, count=len(a)) for c, a in _CTX[f"{side}_arr"].items()}\n    _CTX["lookups"] = lookups\n    explain_diff._CACHE.clear()\n\n\ndef _c3(s: str) -> set:\n    """Character 3-grams of a string (with boundary spaces)."""\n    s = f" {s} "\n    return {s[i : i + 3] for i in range(len(s) - 2)}\n\n\ndef _jacc(a: set, b: set) -> float:\n    """Jaccard of two sets (NaN if both empty)."""\n    if not a and not b:\n        return float("nan")\n    return len(a & b) / len(a | b)\n\n\ndef _idf_jacc(t1: list[str], w1: list[float], t2: list[str], w2: list[float]) -> float:\n    """IDF-weighted token Jaccard."""\n    d1, d2 = dict(zip(t1, w1)), dict(zip(t2, w2))\n    inter = sum(d1[t] for t in d1.keys() & d2.keys())\n    union = sum(d1.values()) + sum(v for t, v in d2.items() if t not in d1)\n    return inter / union if union > 0 else float("nan")\n\n\ndef _side(tokens: list[str], idf: dict, default: float, generic: set) -> tuple[list[float], list[bool]]:\n    """IDF values and generic flags of a token list."""\n    return [idf.get(t, default) for t in tokens], [t in generic for t in tokens]\n\n\ndef _py_block(q_rows: np.ndarray, p_rows: np.ndarray) -> np.ndarray:\n    """Per-pair Python features (PY_FEATURES) for aligned arrays of S1 / pool rows."""\n    C = _CTX\n    lk = C["lookups"]\n    gen_n, gen_a = lk["generic_name"], lk["generic_addr"]\n    out = np.full((len(q_rows), len(PY_FEATURES)), np.nan, dtype=np.float32)\n    last_i, s_cache = -1, None\n    for k in range(len(q_rows)):\n        i, j = int(q_rows[k]), int(p_rows[k])\n        if i != last_i:  # pairs are grouped by S1: prepare the S1 side once\n            ni, nd, ai, ad = lk["idf"].get(C["s_country"][i], ({}, 1.0, {}, 1.0))\n            n1, a1 = C["s_norm_name"][i].split(), C["s_norm_addr"][i].split()\n            nw1, ng1 = _side(n1, ni, nd, gen_n)\n            aw1, ag1 = _side(a1, ai, ad, gen_a)\n            rec1 = {c: C[f"s_{c}"][i] for c in ("house_number", "postcodes", "addr_numbers", "name_numbers")}\n            lm1 = set(C["s_landmark"][i].split())\n            s_cache = (n1, a1, nw1, ng1, aw1, ag1, rec1, lm1, _c3(C["s_norm_name"][i]), _c3(C["s_norm_addr"][i]),\n                       len(C["s_norm_name"][i]), len(C["s_norm_addr"][i]), float(C["s_name_romanized"][i]))\n            last_i = i\n        n1, a1, nw1, ng1, aw1, ag1, rec1, lm1, c3n1, c3a1, ln1, la1, rom1 = s_cache\n        pn, pa = C["p_norm_name"][j], C["p_norm_addr"][j]\n        n2, a2 = pn.split(), pa.split()\n        nw2, ng2 = _side(n2, ni, nd, gen_n)\n        aw2, ag2 = _side(a2, ai, ad, gen_a)\n        rec2 = {c: C[f"p_{c}"][j] for c in ("house_number", "postcodes", "addr_numbers", "name_numbers")}\n        lm2 = set(C["p_landmark"][j].split())\n        fn, _ = explain_diff.explain_features(n1, n2, nw1, nw2, ng1, ng2)\n        fa, _ = explain_diff.explain_features(a1, a2, aw1, aw2, ag1, ag2)\n        num = explain_diff.number_features(rec1, rec2)\n        ln2, la2 = len(pn), len(pa)\n        extra = [\n            _jacc(set(n1), set(n2)), _idf_jacc(n1, nw1, n2, nw2), _jacc(c3n1, _c3(pn)),\n            _jacc(set(a1), set(a2)), _idf_jacc(a1, aw1, a2, aw2), _jacc(c3a1, _c3(pa)) if la1 and la2 else np.nan,\n            min(ln1, ln2) / max(ln1, ln2) if max(ln1, ln2) else np.nan,\n            min(la1, la2) / max(la1, la2) if max(la1, la2) else np.nan,\n            float(la1 == 0), float(la2 == 0), float(bool(rec1["postcodes"])), float(bool(rec2["postcodes"])),\n            float(bool(lm1)), float(bool(lm2)), _jacc(lm1, lm2) if lm1 and lm2 else np.nan,\n            rom1, float(C["p_name_romanized"][j]),\n        ]\n        out[k] = fn + fa + num + extra\n    return out\n\n\ndef _rf_block(q_rows: np.ndarray, p_rows: np.ndarray, specs: list = _RF_SPECS, workers: int = 1) -> np.ndarray:\n    """Vectorised rapidfuzz similarities (0-100) for aligned S1 / pool rows; NaN where a side is empty."""\n    from rapidfuzz import fuzz, process\n    from rapidfuzz.distance import JaroWinkler, Levenshtein\n\n    scorers = {"ratio": fuzz.ratio, "partial_ratio": fuzz.partial_ratio, "token_sort_ratio": fuzz.token_sort_ratio,\n               "token_set_ratio": fuzz.token_set_ratio, "WRatio": fuzz.WRatio,\n               "jw": JaroWinkler.normalized_similarity, "lev": Levenshtein.normalized_similarity}\n    out = np.empty((len(q_rows), len(specs)), dtype=np.float32)\n    sa, pa, sl, pl = _CTX["s_arr"], _CTX["p_arr"], _CTX["s_len"], _CTX["p_len"]\n    texts: dict = {}\n    for c, (_, field, s) in enumerate(specs):\n        if field not in texts:\n            texts[field] = (sa[field][q_rows].tolist(), pa[field][p_rows].tolist())\n        a, b = texts[field]\n        v = process.cpdist(a, b, scorer=scorers[s], workers=workers, dtype=np.float32)\n        if s in ("jw", "lev"):\n            v = v * 100.0  # same 0-100 scale as the fuzz scorers\n        v[(sl[field][q_rows] == 0) | (pl[field][p_rows] == 0)] = np.nan  # unknown, not "different"\n        out[:, c] = v\n    return out\n\n\ndef _worker(args):\n    """Pool task: (q_rows, p_rows, with_py) -> RF + PY feature block, or the pre-ranker RF subset."""\n    q_rows, p_rows, with_py = args\n    if not with_py:\n        return _rf_block(q_rows, p_rows, _PRE_SPECS)\n    rf = _rf_block(q_rows, p_rows)\n    return np.hstack([rf, _py_block(q_rows, p_rows)])\n\n\ndef meta_features(cands: pd.DataFrame, pool_is_s3: np.ndarray, p_rows: np.ndarray, q_rows: np.ndarray,\n                  score_col: str = "cheap_score") -> np.ndarray:\n    """Blocking-meta and source features (META_FEATURES), fully vectorised.\n\n    Ranks/gaps are computed within each S1 over the given candidate rows.\n    Inputs: cands - candidate rows (bitmask, n_channels, <channel>_score,\n            `score_col`); pool_is_s3 - bool per pool row; p_rows, q_rows - row ids.\n    Outputs: float32 array (len(cands), len(META_FEATURES)).\n    """\n    n = len(cands)\n    cols = []\n    bm = np.asarray(cands["bitmask"], dtype=np.int64)\n    for c in SPARSE_CHANNELS:\n        cols.append(((bm & blocking._BIT[c]) > 0).astype(np.float32))\n    for c in SPARSE_CHANNELS:\n        cols.append(np.asarray(cands[f"{c}_score"], dtype=np.float32))\n    cols.append(np.asarray(cands["n_channels"], dtype=np.float32))\n    sc = np.asarray(cands[score_col], dtype=np.float32)\n    order = np.lexsort((-sc, q_rows))\n    qs = q_rows[order]\n    starts = np.flatnonzero(np.r_[True, qs[1:] != qs[:-1]])\n    sizes = np.diff(np.r_[starts, n])\n    rank_sorted = np.arange(n) - np.repeat(starts, sizes)\n    best_sorted = np.repeat(sc[order][starts], sizes)\n    rank, gap, size = np.empty(n, np.float32), np.empty(n, np.float32), np.empty(n, np.float32)\n    rank[order], gap[order], size[order] = rank_sorted, sc[order] - best_sorted, np.repeat(sizes, sizes)\n    cols += [sc, rank, gap, size, pool_is_s3[p_rows].astype(np.float32)]\n    return np.column_stack(cols).astype(np.float32)\n\n\ndef pair_features(q_rows: np.ndarray, p_rows: np.ndarray, with_py: bool = True, n_jobs: int = 1,\n                  block: int = 20_000, log_every: int = 50, log=print) -> np.ndarray:\n    """RF (+ PY) features for aligned S1/pool row arrays, in parallel blocks.\n\n    `set_context` must have been called. Pairs should be grouped by S1 row\n    (the S1-side preparation is reused across consecutive pairs).\n    Inputs: q_rows, p_rows - int arrays; with_py - include PY_FEATURES;\n            n_jobs - worker processes (fork; in-process where unavailable);\n            block - pairs per task; log_every - progress line every N blocks.\n    Outputs: float32 array (n, len(RF_FEATURES) + len(PY_FEATURES)), or\n    (n, len(PRE_RF_FEATURES)) if not with_py.\n    """\n    tasks = [(q_rows[s : s + block], p_rows[s : s + block], with_py) for s in range(0, len(q_rows), block)]\n    t0 = time.time()\n    parts = []\n    pool = blocking._fork_pool(n_jobs)\n    try:\n        it = pool.imap(_worker, tasks, chunksize=1) if pool else map(_worker, tasks)\n        for b, res in enumerate(it):\n            parts.append(res)\n            if log_every and (b + 1) % log_every == 0:\n                done = min((b + 1) * block, len(q_rows))\n                log(f"    features {done:,}/{len(q_rows):,} pairs ({time.time() - t0:.0f}s, {done / max(time.time() - t0, 1e-9):,.0f}/s)")\n    finally:\n        if pool:\n            pool.close()\n            pool.join()\n    width = len(RF_FEATURES) + len(PY_FEATURES) if with_py else len(PRE_RF_FEATURES)\n    return np.vstack(parts) if parts else np.empty((0, width), np.float32)\n\n\ndef rows_for(cands: pd.DataFrame, s1: pd.DataFrame, pool: pd.DataFrame) -> tuple[np.ndarray, np.ndarray]:\n    """Map candidate entity IDs to S1 / pool row ids (fails loudly on unknown IDs)."""\n    q = pd.Index(s1["entity_id"]).get_indexer(cands["s1_id"])\n    p = pd.Index(pool["entity_id"]).get_indexer(cands["cand_id"])\n    assert (q >= 0).all() and (p >= 0).all(), "candidate IDs missing from the record tables"\n    return q.astype(np.int64), p.astype(np.int64)\n\n\ndef build_features(cands: pd.DataFrame, s1: pd.DataFrame, pool: pd.DataFrame, lookups: dict,\n                   n_jobs: int = 1, with_py: bool = True, score_col: str = "cheap_score", log=print) -> pd.DataFrame:\n    """Full feature table for a candidate frame (FEATURES, or PRERANK_FEATURES if not with_py).\n\n    Inputs: cands - s1_id, cand_id, bitmask, n_channels, channel scores,\n            `score_col`; s1, pool - record frames with REC_COLS; lookups -\n            `token_lookups` output; n_jobs; with_py; score_col; log.\n    Outputs: DataFrame (same row order as cands) of float32 features.\n    """\n    cands = cands.reset_index(drop=True)\n    q, p = rows_for(cands, s1, pool)\n    set_context(s1, pool, lookups)\n    is_s3 = np.asarray(pool["entity_id"].str.startswith("S3-"), dtype=bool)\n    meta = meta_features(cands, is_s3, p, q, score_col)\n    # sort by S1 row for the per-S1 cache in the workers, then restore order\n    order = np.argsort(q, kind="stable")\n    rest = pair_features(q[order], p[order], with_py=with_py, n_jobs=n_jobs, log=log)\n    back = np.empty_like(order)\n    back[order] = np.arange(len(order))\n    arr = np.hstack([meta, rest[back]])\n    names = FEATURES if with_py else PRERANK_FEATURES\n    return pd.DataFrame(arr, columns=names)\n\n\ndef time_per_pair(cands: pd.DataFrame, s1: pd.DataFrame, pool: pd.DataFrame, lookups: dict, n_jobs: int,\n                  n: int = 10_000, with_py: bool = True) -> float:\n    """Wall-clock seconds per pair of `build_features` on the first `n` candidate rows (all workers)."""\n    sub = cands.iloc[:n]\n    t0 = time.time()\n    build_features(sub, s1, pool, lookups, n_jobs=n_jobs, with_py=with_py, log=lambda m: None)\n    return (time.time() - t0) / max(len(sub), 1)\n\n\ndef main() -> None:\n    """Print the feature list sizes (smoke test)."""\n    print(f"{len(META_FEATURES)} meta + {len(RF_FEATURES)} rapidfuzz + {len(PY_FEATURES)} python = {len(FEATURES)}")\n\n\nif __name__ == "__main__":\n    main()\n'
features = types.ModuleType('features')
sys.modules['features'] = features
_stage1_source = '"""Stage-1 LightGBM pair classifier (master plan SS15).\n\nTrained on Half A candidate pairs only: 5-fold group-k-fold (groups = S1 id)\ngives out-of-fold probabilities for A (used to pick the judge\'s training\nband), and one model on all of A scores Half B and test. No class\nre-weighting (probabilities are calibrated later on B).\n"""\n\nfrom __future__ import annotations\n\nimport numpy as np\nimport pandas as pd\n\n\ndef lgb_params(cfg: dict, seed: int) -> dict:\n    """LightGBM parameters from the `stage1` config block (plan SS15.1).\n\n    Inputs: cfg - config["stage1"]; seed. Outputs: params dict.\n    """\n    return {\n        "objective": "binary", "learning_rate": cfg.get("lr", 0.05), "num_leaves": cfg.get("num_leaves", 63),\n        "min_data_in_leaf": cfg.get("min_data_in_leaf", 50), "feature_fraction": 0.8, "bagging_fraction": 0.8,\n        "bagging_freq": 1, "lambda_l2": 1.0, "max_bin": cfg.get("max_bin", 127), "seed": seed, "bagging_seed": seed,\n        "feature_fraction_seed": seed, "deterministic": True, "verbose": -1, "num_threads": cfg.get("num_threads", 0),\n    }\n\n\ndef group_folds(groups: np.ndarray, k: int, seed: int) -> np.ndarray:\n    """Fold id per row such that all rows of one group share a fold (seeded, balanced by group count).\n\n    Inputs: groups - group key per row (S1 id); k; seed. Outputs: int array of fold ids.\n    """\n    uniq, inv = np.unique(groups, return_inverse=True)\n    perm = np.random.default_rng(seed).permutation(len(uniq))\n    fold_of_group = np.empty(len(uniq), dtype=np.int32)\n    fold_of_group[perm] = np.arange(len(uniq)) % k\n    return fold_of_group[inv]\n\n\ndef train_oof(X: np.ndarray, y: np.ndarray, groups: np.ndarray, params: dict, folds: int = 5, seed: int = 42,\n              max_rounds: int = 2000, early_stop: int = 50, feature_names: list[str] | None = None, log=print) -> dict:\n    """Group-k-fold OOF training with early stopping on each held-out fold.\n\n    Asserts that no group appears in both the training and validation part.\n    Inputs: X, y, groups (S1 id per row); params; folds; seed; max_rounds;\n            early_stop; feature_names; log.\n    Outputs: {"oof": probabilities, "best_iters": [...], "fold_auc": [...],\n              "models": [boosters]}.\n    """\n    import lightgbm as lgb\n    from sklearn.metrics import roc_auc_score\n\n    fid = group_folds(groups, folds, seed)\n    oof = np.zeros(len(y), dtype=np.float32)\n    best, aucs, models = [], [], []\n    for f in range(folds):\n        va = fid == f\n        tr = ~va\n        assert not set(np.unique(groups[va]).tolist()) & set(np.unique(groups[tr]).tolist()), "group leak between folds"\n        dtr = lgb.Dataset(X[tr], label=y[tr], feature_name=feature_names or "auto", free_raw_data=True)\n        dva = lgb.Dataset(X[va], label=y[va], reference=dtr)\n        m = lgb.train(params, dtr, num_boost_round=max_rounds, valid_sets=[dva],\n                      callbacks=[lgb.early_stopping(early_stop, verbose=False)])\n        oof[va] = m.predict(X[va], num_iteration=m.best_iteration)\n        best.append(int(m.best_iteration))\n        aucs.append(float(roc_auc_score(y[va], oof[va])) if 0 < y[va].sum() < va.sum() else float("nan"))\n        models.append(m)\n        log(f"    fold {f}: best_iter {best[-1]}, AUC {aucs[-1]:.5f}")\n    return {"oof": oof, "best_iters": best, "fold_auc": aucs, "models": models}\n\n\ndef train_full(X: np.ndarray, y: np.ndarray, params: dict, num_rounds: int, feature_names: list[str] | None = None):\n    """One model on all rows with a fixed number of rounds (from the OOF best iterations).\n\n    Outputs: lightgbm.Booster.\n    """\n    import lightgbm as lgb\n\n    return lgb.train(params, lgb.Dataset(X, label=y, feature_name=feature_names or "auto"), num_boost_round=num_rounds)\n\n\ndef predict(model, X: np.ndarray, num_threads: int = 0) -> np.ndarray:\n    """Probabilities from a trained booster (float32)."""\n    return model.predict(X, num_threads=num_threads).astype(np.float32)\n\n\ndef eval_by_group(y: np.ndarray, p: np.ndarray, country: np.ndarray) -> dict:\n    """AUC and log-loss overall and per country label (reporting only, never a feature).\n\n    Inputs: labels, probabilities, country label per row.\n    Outputs: {"ALL": {...}, "<country>": {...}}.\n    """\n    from sklearn.metrics import log_loss, roc_auc_score\n\n    out = {}\n    for key, m in [("ALL", np.ones(len(y), bool))] + [(c, country == c) for c in sorted(set(country.tolist()))]:\n        yy, pp = y[m], np.clip(p[m], 1e-7, 1 - 1e-7)\n        ok = 0 < yy.sum() < len(yy)\n        out[key] = {"n": int(m.sum()), "pos_rate": round(float(yy.mean()), 5) if len(yy) else None,\n                    "auc": round(float(roc_auc_score(yy, pp)), 6) if ok else None,\n                    "logloss": round(float(log_loss(yy, pp, labels=[0, 1])), 6) if len(yy) else None}\n    return out\n\n\ndef main() -> None:\n    """Tiny synthetic run (smoke test)."""\n    rng = np.random.default_rng(0)\n    X = rng.normal(size=(4000, 5)).astype(np.float32)\n    y = (X[:, 0] + 0.5 * rng.normal(size=4000) > 0).astype(np.int8)\n    g = np.repeat(np.arange(400), 10)\n    r = train_oof(X, y, g, lgb_params({"lr": 0.1}, 0), folds=3, max_rounds=100)\n    print(pd.Series(r["fold_auc"]).round(4).tolist())\n\n\nif __name__ == "__main__":\n    main()\n'
stage1 = types.ModuleType('stage1')
sys.modules['stage1'] = stage1
_decoder_source = '"""Expected-F0.5 decoder, calibration and the macro-F0.5 scorer on pair tables (plan SS18.2, SS20, SS28.3).\n\nFor every S1 entity the candidates are sorted by calibrated probability and\neach top-k set (k = 0..n, where k = 0 is the "empty" answer) is valued by its\nexpected F0.5 under independent Bernoulli matches, with an extra Bernoulli q\nfor "a true match exists outside the candidate set". The best k wins.\n\nThe reference implementation (plan SS28.3) loops per entity; here the same\ncomputation is vectorised over entities: prefix / suffix Poisson-binomial\npmfs are built by one column update per candidate, and E[F](k) is an\neinsum of the TP pmf, the FN pmf and a fixed score table.\n"""\n\nfrom __future__ import annotations\n\nimport numpy as np\nimport pandas as pd\n\nBETA2 = 0.25  # F0.5\n\n\ndef score_table(k: int, n_fn: int, beta2: float = BETA2) -> np.ndarray:\n    """F-beta value for a top-k prediction as a (tp = 0..k) x (fn = 0..n_fn) table (official convention).\n\n    k = 0: 1 if fn = 0 else 0; k > 0 and tp = 0: 0; else (1+b2)tp / ((1+b2)tp + b2 fn + (k - tp)).\n    """\n    tp = np.arange(k + 1)[:, None].astype(np.float64)\n    fn = np.arange(n_fn + 1)[None, :].astype(np.float64)\n    if k == 0:\n        return (fn == 0).astype(np.float64)\n    denom = (1 + beta2) * tp + beta2 * fn + (k - tp)\n    return np.where(tp > 0, (1 + beta2) * tp / np.maximum(denom, 1e-12), 0.0)\n\n\ndef expected_f_matrix(P: np.ndarray, q: np.ndarray, beta2: float = BETA2) -> np.ndarray:\n    """E[F-beta] of every top-k prediction for a batch of entities.\n\n    Inputs: P - (E, n) probabilities sorted descending per row (pad with 0);\n            q - (E,) probability of a true match outside the candidates.\n    Outputs: (E, n + 1) expected scores for k = 0..n.\n    """\n    E, n = P.shape\n    # prefix[k]: pmf of TP among the first k candidates, shape (E, k + 1)\n    prefix = [np.ones((E, 1))]\n    for j in range(n):\n        prev, p = prefix[-1], P[:, j : j + 1]\n        cur = np.zeros((E, j + 2))\n        cur[:, :-1] += prev * (1 - p)\n        cur[:, 1:] += prev * p\n        prefix.append(cur)\n    # suffix[k]: pmf of FN among candidates k..n-1 plus the outside Bernoulli q, shape (E, n - k + 2)\n    suffix = [None] * (n + 1)\n    cur = np.stack([1 - q, q], axis=1)\n    suffix[n] = cur\n    for j in range(n - 1, -1, -1):\n        p = P[:, j : j + 1]\n        nxt = np.zeros((E, cur.shape[1] + 1))\n        nxt[:, :-1] += cur * (1 - p)\n        nxt[:, 1:] += cur * p\n        cur = nxt\n        suffix[j] = cur\n    out = np.empty((E, n + 1))\n    for k in range(n + 1):\n        S = score_table(k, suffix[k].shape[1] - 1, beta2)\n        out[:, k] = np.einsum("et,tf,ef->e", prefix[k], S, suffix[k], optimize=True)\n    return out\n\n\ndef sharpen(p: np.ndarray, lam: float) -> np.ndarray:\n    """p\' = sigmoid(lam * logit(p)) (lam < 1 softens, > 1 sharpens; plan SS18.2)."""\n    if lam == 1.0:\n        return p\n    p = np.clip(p, 1e-6, 1 - 1e-6)\n    return 1.0 / (1.0 + np.exp(-lam * np.log(p / (1 - p))))\n\n\ndef _grouped(df: pd.DataFrame, pcol: str, max_n: int):\n    """Sort pairs by (s1, p desc); return (sorted frame, group starts, sizes, rank within group)."""\n    d = df.sort_values(["s1_id", pcol], ascending=[True, False], kind="stable").reset_index(drop=True)\n    s = d["s1_id"].to_numpy()\n    starts = np.flatnonzero(np.r_[True, s[1:] != s[:-1]]) if len(d) else np.empty(0, int)\n    sizes = np.diff(np.r_[starts, len(d)])\n    rank = np.arange(len(d)) - np.repeat(starts, sizes)\n    return d, starts, sizes, rank\n\n\ndef decode(df: pd.DataFrame, pcol: str = "p", q: float | np.ndarray = 0.0, max_n: int = 20, min_p: float = 0.0,\n           batch: int = 50_000) -> pd.DataFrame:\n    """Expected-F0.5 top-k decision for every S1 in a pair table.\n\n    Inputs: df - pairs with s1_id, cand_id and calibrated probability `pcol`;\n            q - outside-candidates match probability (scalar or per-row array\n            aligned with df, constant within an S1); max_n - candidates\n            considered per S1 (the rest are ignored); min_p - probabilities\n            below this are treated as 0; batch - entities per vectorised batch.\n    Outputs: the pairs chosen (s1_id, cand_id, pcol) — S1s absent from the\n    result predict the empty set.\n    """\n    if len(df) == 0:\n        return df.iloc[:0][["s1_id", "cand_id", pcol]]\n    d = df[["s1_id", "cand_id", pcol]].copy()\n    d["_q"] = q if np.ndim(q) == 0 else np.asarray(q)\n    d, starts, sizes, rank = _grouped(d, pcol, max_n)\n    keep_rank = rank < max_n\n    E = len(starts)\n    n = int(min(max_n, sizes.max()))\n    P = np.zeros((E, n))\n    ent = np.repeat(np.arange(E), sizes)\n    p = d[pcol].to_numpy(np.float64)\n    p = np.where(p < min_p, 0.0, p)\n    P[ent[keep_rank], rank[keep_rank]] = p[keep_rank]\n    qe = d["_q"].to_numpy(np.float64)[starts]\n    best = np.empty(E, dtype=np.int64)\n    for s in range(0, E, batch):\n        best[s : s + batch] = expected_f_matrix(P[s : s + batch], qe[s : s + batch]).argmax(axis=1)\n    chosen = rank < np.repeat(best, sizes)\n    return d.loc[chosen, ["s1_id", "cand_id", pcol]].reset_index(drop=True)\n\n\ndef threshold_decode(df: pd.DataFrame, pcol: str, t: float) -> pd.DataFrame:\n    """Baseline: every candidate with probability >= t (plan SS20.5 comparison)."""\n    return df.loc[df[pcol] >= t, ["s1_id", "cand_id", pcol]].reset_index(drop=True)\n\n\ndef macro_f05(pred: pd.DataFrame, truth: pd.DataFrame, s1_ids, beta2: float = BETA2, return_per_entity: bool = False):\n    """Official macro F0.5 over the given S1 entities (plan SS1.2; same rules as metrics.f05_entity).\n\n    Inputs: pred - predicted pairs (s1_id, cand_id); truth - true pairs\n            (s1_id, match_id), may include pairs outside the candidates;\n            s1_ids - every evaluated S1 (singletons included).\n    Outputs: mean F0.5 (and the per-entity Series if requested).\n    """\n    ids = pd.Index(pd.unique(np.asarray(list(s1_ids))))\n    t = truth[truth["s1_id"].isin(ids)]\n    pr = pred[pred["s1_id"].isin(ids)]\n    n_true = t.groupby("s1_id").size().reindex(ids, fill_value=0).to_numpy()\n    n_pred = pr.groupby("s1_id").size().reindex(ids, fill_value=0).to_numpy()\n    hit = pr.merge(t, left_on=["s1_id", "cand_id"], right_on=["s1_id", "match_id"], how="inner")\n    tp = hit.groupby("s1_id").size().reindex(ids, fill_value=0).to_numpy()\n    fn, fp = n_true - tp, n_pred - tp\n    with np.errstate(invalid="ignore", divide="ignore"):\n        f = (1 + beta2) * tp / ((1 + beta2) * tp + beta2 * fn + fp)\n    f = np.where((n_true == 0) & (n_pred == 0), 1.0, np.nan_to_num(f, nan=0.0))\n    f = np.where(tp == 0, np.where((n_true == 0) & (n_pred == 0), 1.0, 0.0), f)\n    s = pd.Series(f, index=ids)\n    return (float(s.mean()), s) if return_per_entity else float(s.mean())\n\n\nclass Isotonic:\n    """Isotonic calibration p -> empirical match rate (sklearn), with a Platt fallback (plan SS18.2)."""\n\n    def __init__(self, kind: str = "isotonic"):\n        """kind: "isotonic" or "platt"."""\n        self.kind = kind\n        self.model = None\n\n    def fit(self, p: np.ndarray, y: np.ndarray) -> "Isotonic":\n        """Fit on raw probabilities p and 0/1 labels y."""\n        if self.kind == "isotonic":\n            from sklearn.isotonic import IsotonicRegression\n\n            self.model = IsotonicRegression(y_min=0.0, y_max=1.0, out_of_bounds="clip").fit(p, y)\n        else:\n            from sklearn.linear_model import LogisticRegression\n\n            x = np.log(np.clip(p, 1e-6, 1 - 1e-6) / (1 - np.clip(p, 1e-6, 1 - 1e-6)))\n            self.model = LogisticRegression(C=1e4).fit(x[:, None], y)\n        return self\n\n    def predict(self, p: np.ndarray) -> np.ndarray:\n        """Calibrated probabilities (float64)."""\n        if self.kind == "isotonic":\n            return self.model.predict(p).astype(np.float64)\n        x = np.log(np.clip(p, 1e-6, 1 - 1e-6) / (1 - np.clip(p, 1e-6, 1 - 1e-6)))\n        return self.model.predict_proba(x[:, None])[:, 1]\n\n\ndef ece(p: np.ndarray, y: np.ndarray, bins: int = 15) -> float:\n    """Expected calibration error with equal-width bins."""\n    idx = np.minimum((p * bins).astype(int), bins - 1)\n    tot = 0.0\n    for b in range(bins):\n        m = idx == b\n        if m.any():\n            tot += m.sum() * abs(p[m].mean() - y[m].mean())\n    return float(tot / max(len(p), 1))\n\n\ndef main() -> None:\n    """Check the vectorised decoder against the reference loop on random entities (smoke test)."""\n    rng = np.random.default_rng(0)\n    P = -np.sort(-rng.random((5, 6)) ** 3, axis=1)\n    print(expected_f_matrix(P, np.full(5, 0.05)).argmax(axis=1))\n\n\nif __name__ == "__main__":\n    main()\n'
decoder = types.ModuleType('decoder')
sys.modules['decoder'] = decoder
_exclusivity_source = '"""One-owner rule: each S2/S3 record belongs to at most one S1 (plan SS19).\n\nEDA E4 found 0 of 7,638,365 matched IDs shared between two S1s, so the\ndefault mode is `hard` (memory.md SS5); `soft` and `none` stay available and\nare compared on Half B.\n"""\n\nfrom __future__ import annotations\n\nimport numpy as np\nimport pandas as pd\n\n\ndef hard_one_owner(df: pd.DataFrame, pcol: str = "p", p_min: float = 0.05) -> np.ndarray:\n    """Greedy global assignment (plan SS19.1).\n\n    Among pairs with p >= p_min, sorted by p descending, a record goes to the\n    first S1 that claims it; the other claimants\' probabilities become 0.\n    Pairs below p_min are left unchanged.\n\n    Inputs: df - pairs (s1_id, cand_id, pcol); pcol; p_min.\n    Outputs: adjusted probability array aligned with df\'s rows.\n    """\n    p = df[pcol].to_numpy(np.float64).copy()\n    idx = np.flatnonzero(p >= p_min)\n    if len(idx) == 0:\n        return p\n    sub = pd.DataFrame({"cand_id": df["cand_id"].to_numpy()[idx], "p": p[idx], "i": idx})\n    sub = sub.sort_values(["p", "i"], ascending=[False, True], kind="stable")\n    lost = sub["i"].to_numpy()[sub["cand_id"].duplicated(keep="first").to_numpy()]\n    p[lost] = 0.0\n    return p\n\n\ndef soft_one_owner(df: pd.DataFrame, pcol: str = "p", gamma: float = 1.0) -> np.ndarray:\n    """p\'(e, r) = p(e, r) * (p(e, r) / sum_e\' p(e\', r)) ** gamma (plan SS19.2)."""\n    p = df[pcol].to_numpy(np.float64)\n    tot = df.assign(_p=p).groupby("cand_id")["_p"].transform("sum").to_numpy()\n    share = np.divide(p, tot, out=np.zeros_like(p), where=tot > 0)\n    return p * share ** gamma\n\n\ndef apply(df: pd.DataFrame, mode: str, pcol: str = "p", p_min: float = 0.05, gamma: float = 1.0) -> np.ndarray:\n    """Dispatch on mode: "none" | "soft" | "hard". Outputs: adjusted probabilities aligned with df."""\n    if mode == "none":\n        return df[pcol].to_numpy(np.float64).copy()\n    if mode == "soft":\n        return soft_one_owner(df, pcol, gamma)\n    if mode == "hard":\n        return hard_one_owner(df, pcol, p_min)\n    raise ValueError(f"unknown exclusivity mode {mode!r}")\n\n\ndef main() -> None:\n    """Tiny example (smoke test)."""\n    df = pd.DataFrame({"s1_id": ["a", "b", "b"], "cand_id": ["x", "x", "y"], "p": [0.9, 0.6, 0.7]})\n    print(hard_one_owner(df), soft_one_owner(df))\n\n\nif __name__ == "__main__":\n    main()\n'
exclusivity = types.ModuleType('exclusivity')
sys.modules['exclusivity'] = exclusivity
_scramble_source = '"""Scrambled-letter transform (master plan SS21): a random a-z permutation applied\nidentically to every record, digits and spaces unchanged.\n\nAbbreviation, typo and reorder relations survive the transform while the\nvocabulary is destroyed, so a model that still matches well has learned\nstructure rather than US/India words (proxy for the unseen country).\n"""\n\nfrom __future__ import annotations\n\nimport random\nimport string\n\n\ndef make_scrambler(seed: int) -> dict[int, int]:\n    """Build a str.translate table for one random a-z permutation (same for upper case).\n\n    Inputs: seed. Outputs: translation table usable with `str.translate`.\n    """\n    rng = random.Random(seed)\n    perm = list(string.ascii_lowercase)\n    rng.shuffle(perm)\n    table = {ord(a): ord(b) for a, b in zip(string.ascii_lowercase, perm)}\n    table.update({ord(a.upper()): ord(b.upper()) for a, b in zip(string.ascii_lowercase, perm)})\n    return table\n\n\ndef scramble_texts(texts, table: dict[int, int]) -> list[str]:\n    """Apply a scrambler table to every text. Inputs: iterable of str; table. Outputs: list."""\n    return [t.translate(table) for t in texts]\n\n\ndef scramble_df(df, table: dict[int, int], cols=("business_name", "business_address")):\n    """Return a copy of a record frame with the text columns scrambled."""\n    out = df.copy()\n    for c in cols:\n        if c in out:\n            out[c] = scramble_texts(out[c].tolist(), table)\n    return out\n\n\ndef main() -> None:\n    """Smoke test."""\n    t = make_scrambler(42)\n    print("Main St 12".translate(t))\n\n\nif __name__ == "__main__":\n    main()\n'
scramble = types.ModuleType('scramble')
sys.modules['scramble'] = scramble
_check_outputs_source = '"""Pre-flight checks for output/matching_results.tsv and output/candidate_pairs.tsv.\n\nRuns the assertions from master plan SS22.2 *before* the official validator,\nso a bug is caught with a clear message instead of a generic FAIL. This does\nnot replace `utils/validate_submission.py` — always run both (CLAUDE.md SS9).\n\nMemory-lean by design (the laptop has < 1 GB free): every file is streamed\nline by line, IDs are encoded as int64 in NumPy arrays (prefix digit x 1e12 +\nnumber) instead of Python string sets, and the candidate file is checked\nline-aligned with the matching file (dict fallback only for rows whose order\ndiffers).\n"""\n\nfrom __future__ import annotations\n\nimport argparse\nimport re\nimport sys\nfrom array import array\nfrom pathlib import Path\n\nimport numpy as np\n\n_ID_RE = re.compile(r"^S([123])-(\\d{1,12})$")\n_BASE = 10**12\nMAX_PROBLEMS = 50\n\n\ndef encode_id(eid: str) -> int:\n    """\'S2-888394598\' -> 2 * 1e12 + 888394598; -1 if the ID does not have the S<k>-<digits> shape."""\n    m = _ID_RE.match(eid)\n    return int(m.group(1)) * _BASE + int(m.group(2)) if m else -1\n\n\ndef _first_column_codes(path: Path) -> np.ndarray:\n    """Encoded IDs of the first column of a source TSV (header skipped), streamed."""\n    out = array("q")\n    with open(path, encoding="utf-8") as f:\n        next(f)\n        for line in f:\n            eid = line.split("\\t", 1)[0].rstrip("\\n")\n            if eid:\n                out.append(encode_id(eid))\n    return np.frombuffer(out, dtype=np.int64) if len(out) else np.empty(0, np.int64)\n\n\ndef _s1_countries(path: Path) -> tuple[np.ndarray, np.ndarray, list[str]]:\n    """(encoded S1 IDs, country code per row, country names) from test_source1.tsv, streamed."""\n    codes, cty = array("q"), array("i")\n    names: dict[str, int] = {}\n    with open(path, encoding="utf-8") as f:\n        header = next(f).rstrip("\\n").split("\\t")\n        ci = header.index("country")\n        for line in f:\n            parts = line.rstrip("\\n").split("\\t")\n            if not parts[0]:\n                continue\n            codes.append(encode_id(parts[0]))\n            cty.append(names.setdefault(parts[ci] if ci < len(parts) else "", len(names)))\n    inv = sorted(names, key=names.get)\n    return np.frombuffer(codes, dtype=np.int64), np.frombuffer(cty, dtype=np.int32), inv\n\n\ndef _parse_row(line: str, lineno: int, name: str, problems: list[str]) -> tuple[str, list[str]]:\n    """Split one output row into (s1_id, ids) and record format problems (spaces, quotes, dupes, prefixes)."""\n    line = line.rstrip("\\n")\n    if "\\r" in line:\n        problems.append(f"{name}:{lineno}: carriage return (Windows line ending)")\n        line = line.rstrip("\\r")\n    if line.count("\\t") != 1:\n        problems.append(f"{name}:{lineno}: expected exactly one tab, got {line.count(chr(9))}")\n    s1, _, rest = line.partition("\\t")\n    if " " in line or \'"\' in line or "\'" in line:\n        problems.append(f"{name}:{lineno}: spaces or quotes in the row")\n    ids = rest.split(",") if rest else []\n    if any(not i for i in ids):\n        problems.append(f"{name}:{lineno}: empty ID in the list (stray comma)")\n    if len(set(ids)) != len(ids):\n        problems.append(f"{name}:{lineno}: duplicate IDs in the list")\n    for i in ids:\n        if not (i.startswith("S2-") or i.startswith("S3-")):\n            problems.append(f"{name}:{lineno}: id {i!r} has no S2-/S3- prefix")\n            break\n    return s1, ids\n\n\ndef check_outputs(out_dir: Path, test_dir: Path, check_ids: bool = True) -> list[str]:\n    """Run every pre-flight assertion; return a list of problem descriptions (empty = PASS).\n\n    Inputs: out_dir - folder with matching_results.tsv (+ candidate_pairs.tsv);\n            test_dir - folder with test_source1/2/3.tsv; check_ids - also\n            verify that every matched/candidate ID exists in test S2/S3.\n    Outputs: list of human-readable problems (capped at MAX_PROBLEMS).\n    """\n    problems: list[str] = []\n    matching_path, candidate_path = out_dir / "matching_results.tsv", out_dir / "candidate_pairs.tsv"\n    s1_path = test_dir / "test_source1.tsv"\n    for p in (matching_path, s1_path):\n        if not p.exists():\n            return [f"missing {p}"]\n    req, req_cty, cty_names = _s1_countries(s1_path)\n    if (req < 0).any():\n        problems.append("test_source1.tsv has IDs that are not S1-<digits> (encoder assumption broken)")\n\n    has_cand = candidate_path.exists()\n    if not has_cand:\n        problems.append(f"missing {candidate_path} (required in the final zip)")\n    rows_s1 = array("q")\n    n_pred = array("i")\n    matched_codes, cand_codes = array("q"), array("q")\n    pending_m: dict[str, list[str]] = {}\n    pending_c: dict[str, list[str]] = {}\n    with open(matching_path, encoding="utf-8", newline="") as fm:\n        fc = open(candidate_path, encoding="utf-8", newline="") if has_cand else None\n        try:\n            hm = next(fm).rstrip("\\r\\n")\n            if hm != "source1_entity_id\\tmatched_entity_ids":\n                problems.append(f"matching header is {hm!r}")\n            if fc:\n                hc = next(fc).rstrip("\\r\\n")\n                if hc != "source1_entity_id\\tcandidate_entity_ids":\n                    problems.append(f"candidate header is {hc!r}")\n            for lineno, line in enumerate(fm, start=2):\n                s1, ids = _parse_row(line, lineno, "matching", problems)\n                rows_s1.append(encode_id(s1))\n                n_pred.append(len(ids))\n                for i in ids:\n                    matched_codes.append(encode_id(i))\n                if fc is not None:\n                    cline = fc.readline()\n                    if not cline:\n                        pending_m[s1] = ids\n                        continue\n                    cs1, cids = _parse_row(cline, lineno, "candidate", problems)\n                    for i in cids:\n                        cand_codes.append(encode_id(i))\n                    if cs1 == s1:\n                        extra = set(ids) - set(cids)\n                        if extra:\n                            problems.append(f"{s1}: matched ids not in its candidate list: {sorted(extra)[:5]}")\n                    else:  # different row order: resolve after the pass\n                        pending_m[s1] = ids\n                        pending_c[cs1] = cids\n                if len(problems) > MAX_PROBLEMS:\n                    break\n            if fc is not None:\n                for lineno, cline in enumerate(fc, start=10**9):\n                    cs1, cids = _parse_row(cline, lineno, "candidate", problems)\n                    pending_c[cs1] = cids\n                    for i in cids:\n                        cand_codes.append(encode_id(i))\n        finally:\n            if fc:\n                fc.close()\n    for s1, ids in pending_m.items():\n        cids = pending_c.get(s1)\n        if cids is None:\n            problems.append(f"{s1}: row missing from candidate_pairs.tsv")\n        elif set(ids) - set(cids):\n            problems.append(f"{s1}: matched ids not in its candidate list: {sorted(set(ids) - set(cids))[:5]}")\n\n    rows = np.frombuffer(rows_s1, dtype=np.int64)\n    uniq, counts = np.unique(rows, return_counts=True)\n    if (counts > 1).any():\n        problems.append(f"{int((counts > 1).sum())} duplicate S1 rows in matching_results.tsv")\n    missing = np.setdiff1d(req, uniq)\n    if len(missing):\n        problems.append(f"{len(missing)} required S1 entities missing from matching_results.tsv")\n    extra = np.setdiff1d(uniq, req)\n    if len(extra):\n        problems.append(f"{len(extra)} rows use an S1 ID not in the test set")\n    if check_ids:\n        valid = np.unique(np.concatenate([_first_column_codes(test_dir / f"test_source{s}.tsv") for s in (2, 3)\n                                          if (test_dir / f"test_source{s}.tsv").exists()]))\n        for name, codes in (("matched", matched_codes), ("candidate", cand_codes)):\n            arr = np.frombuffer(codes, dtype=np.int64) if len(codes) else np.empty(0, np.int64)\n            bad = int((~np.isin(arr, valid)).sum()) if len(valid) else 0\n            if bad:\n                problems.append(f"{bad} {name} IDs do not exist in test_source2/3")\n    # France / per-country presence: every country of test_source1 must appear in the output.\n    present = np.isin(req, uniq)\n    for k, name in enumerate(cty_names):\n        m = req_cty == k\n        if m.any() and not present[m].all():\n            problems.append(f"country {name!r}: {int((~present[m]).sum())} S1 rows missing")\n    return problems[:MAX_PROBLEMS]\n\n\ndef output_summary(out_dir: Path, test_dir: Path) -> dict:\n    """Per-country predicted-empty rate and mean predicted set size (distribution sanity, plan SS22.2)."""\n    req, req_cty, names = _s1_countries(test_dir / "test_source1.tsv")\n    size = {}\n    with open(out_dir / "matching_results.tsv", encoding="utf-8") as f:\n        next(f)\n        for line in f:\n            s1, _, rest = line.rstrip("\\n").partition("\\t")\n            size[encode_id(s1)] = len(rest.split(",")) if rest else 0\n    k = np.array([size.get(int(c), 0) for c in req])\n    return {n: {"n_s1": int((req_cty == i).sum()), "pred_empty_rate": round(float((k[req_cty == i] == 0).mean()), 5),\n                "mean_pred_size": round(float(k[req_cty == i].mean()), 3)} for i, n in enumerate(names)}\n\n\ndef main() -> None:\n    """CLI: `python -m src.check_outputs --out-dir output --test-dir student_resource/dataset/test`."""\n    parser = argparse.ArgumentParser(description=__doc__)\n    parser.add_argument("--out-dir", default="output")\n    parser.add_argument("--test-dir", default="../../student_resource/dataset/test")\n    parser.add_argument("--no-check-ids", action="store_true", help="skip the S2/S3 existence check")\n    args = parser.parse_args()\n\n    problems = check_outputs(Path(args.out_dir), Path(args.test_dir), check_ids=not args.no_check_ids)\n    print(output_summary(Path(args.out_dir), Path(args.test_dir)))\n    if problems:\n        print(f"FAIL — {len(problems)} issue(s):")\n        for i, p in enumerate(problems, 1):\n            print(f"  {i}. {p}")\n        sys.exit(1)\n    print("PASS — check_outputs found no issues.")\n\n\nif __name__ == "__main__":\n    main()\n'
